const skirCode = `// shapes.skir

struct Point {
  x: float32;
  y: float32;
}

enum Shape {
  empty;
  polygon: [Point];
  circle: struct {
    center: Point;
    radius: float32;
  };
  union: [Shape];
}

method GetArea(
  Shape
): float32 = 412938;`

